mapper.select:
/* Attd01Mapper.selectSchInfoList */ SELECT A.CMPNY_CD AS cmpnyCd , A.SITE_CD AS siteCd , A.SCH_CD AS schCd , A.SCH_NO AS schNo , A.SCH_TYPE AS schType , FNC_CMM_INFO_SRCH( A.CMPNY_CD , 'SYST_VAL' , A.SCH_TYPE , 'SYS019' ) AS schTypeNm , A.APPLY_DATE AS applyDate
, A.FST_SCH_STR_TIME AS fstSchStrTime , A.FST_SCH_END_TIME AS fstSchEndTime , CONCAT( A.FST_SCH_STR_TIME , '-' , A.FST_SCH_END_TIME ) AS fstSchTime , A.FST_SCH_BRK_MIN AS fstSchBrkMin , A.FST_BRK_STR_TIME AS fstBrkStrTime , A.FST_BRK_END_TIME AS fstBrkEndTime
, A.SEC_SCH_STR_TIME AS secSchStrTime , A.SEC_SCH_END_TIME AS secSchEndTime , CONCAT( A.SEC_SCH_STR_TIME , '-' , A.SEC_SCH_END_TIME ) AS secSchTime , A.SEC_SCH_BRK_MIN AS secSchBrkMin , A.SEC_BRK_STR_TIME AS secBrkStrTime , A.SEC_BRK_END_TIME AS secBrkEndTime
, A.USE_YN AS useYn , FNC_CMM_INFO_SRCH( A.CMPNY_CD , 'SYST_VAL' , A.USE_YN , 'SYS003' ) AS useYnNm
, A.LINK_SRC_CMPNY_CD AS linkSrcCmpnyCd
, A.PRE_FIXED_OT_STR_TIME AS preFixedOtStrTime , A.PRE_FIXED_OT_END_TIME AS preFixedOtEndTime , A.FIXED_OT_STR_TIME AS fixedOtStrTime , A.FIXED_OT_END_TIME AS fixedOtEndTime FROM TB_SCH_MGMT A WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd}
AND A.SITE_CD = #{siteCd}
AND A.SCH_NO = #{schNo}
AND A.SCH_TYPE = #{schType}
AND A.USE_YN = #{useYn}

    /* Attd01Mapper.selectSchNoCount */
    SELECT
    	COUNT(*)
	FROM TB_SCH_MGMT
	WHERE CMPNY_CD = #{gvCmpnyCd}
	  AND SITE_CD = #{siteCd}
	  AND SCH_NO = #{schNo}


	  	AND SCH_CD != #{schCd}

/* Attd01Mapper.selectSchCd */
SELECT FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, CONCAT('SCH_CD-', #{siteCd}))
FROM DUAL

/* Attd01Mapper.selectSiteLinkSrcCmpny */
SELECT A.LINK_SRC_CMPNY_CD
FROM TB_SITE A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD  = #{siteCd}

    /* Attd01Mapper.selectSchHistIdx */
    SELECT COUNT(*)
	FROM TB_SCH_MGMT_HIST A
	WHERE A.CMPNY_CD = #{gvCmpnyCd}
	  AND A.SITE_CD = #{siteCd}
	  AND A.SCH_CD = #{schCd}

/* Attd01Mapper.selectSchTimeBreakChanged */
SELECT COUNT(*) FROM TB_SCH_MGMT A WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{siteCd} AND A.SCH_CD = #{schCd} AND ( NOT (A.FST_SCH_STR_TIME <=> REPLACE(#{fstSchStrTime}, ':', '')) OR NOT (A.FST_SCH_END_TIME <=> REPLACE(#{fstSchEndTime}, ':', '')) OR NOT (A.FST_SCH_BRK_MIN <=> #{fstSchBrkMin}) OR NOT (A.FST_BRK_STR_TIME <=> NULLIF(REPLACE(IFNULL(#{fstBrkStrTime}, ''), ':', ''), '')) OR NOT (A.FST_BRK_END_TIME <=> NULLIF(REPLACE(IFNULL(#{fstBrkEndTime}, ''), ':', ''), '')) OR NOT (A.SEC_SCH_STR_TIME <=> REPLACE(IFNULL(#{secSchStrTime}, ''), ':', '')) OR NOT (A.SEC_SCH_END_TIME <=> REPLACE(IFNULL(#{secSchEndTime}, ''), ':', '')) OR NOT (A.SEC_SCH_BRK_MIN <=> IFNULL(#{secSchBrkMin}, '0')) OR NOT (A.SEC_BRK_STR_TIME <=> NULLIF(REPLACE(IFNULL(#{secBrkStrTime}, ''), ':', ''), '')) OR NOT (A.SEC_BRK_END_TIME <=> NULLIF(REPLACE(IFNULL(#{secBrkEndTime}, ''), ':', ''), ''))
OR NOT (A.PRE_FIXED_OT_STR_TIME <=> NULLIF(REPLACE(IFNULL(#{preFixedOtStrTime}, ''), ':', ''), '')) OR NOT (A.PRE_FIXED_OT_END_TIME <=> NULLIF(REPLACE(IFNULL(#{preFixedOtEndTime}, ''), ':', ''), '')) OR NOT (A.FIXED_OT_STR_TIME <=> NULLIF(REPLACE(IFNULL(#{fixedOtStrTime}, ''), ':', ''), '')) OR NOT (A.FIXED_OT_END_TIME <=> NULLIF(REPLACE(IFNULL(#{fixedOtEndTime}, ''), ':', ''), '')) )

/* Attd01Mapper.selectFutureWorkPlanDaysBySchCd */

SELECT
    A.USER_CD     AS userCd
    , A.WORK_YMD  AS workYmd
FROM TB_USER_WORK_PLAN A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.WORK_PLAN_CD = #{schCd}
  AND A.WORK_YMD  >=  #{fromYmd}
ORDER BY A.USER_CD, A.WORK_YMD

/* Attd01Mapper.selectSchUseYn */

SELECT A.USE_YN
FROM TB_SCH_MGMT A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.SCH_CD = #{schCd}

/* Attd01Mapper.selectAssignedUsersBySchCd */
WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{scopeNodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD ) SELECT B.USER_NM AS userNm , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'NODE', A.SITE_CD, B.NODE_CD) AS nodeNm , DATE_FORMAT(STR_TO_DATE(MIN(A.WORK_YMD), '%Y%m%d'), '%Y-%m-%d') AS firstWorkYmd , DATE_FORMAT(STR_TO_DATE(MAX(A.WORK_YMD), '%Y%m%d'), '%Y-%m-%d') AS lastWorkYmd , COUNT(*) AS assignedDayCount FROM TB_USER_WORK_PLAN A INNER JOIN TB_USER B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.USER_CD = B.USER_CD ) INNER JOIN node_tree NT ON ( B.CMPNY_CD = NT.CMPNY_CD AND B.SITE_CD = NT.SITE_CD AND B.NODE_CD = NT.NODE_CD ) WHERE A.CMPNY_CD = #{cmpnyCd} AND A.SITE_CD = #{siteCd} AND A.WORK_PLAN_CD = #{schCd} AND A.WORK_YMD >= #{fromYmd} GROUP BY A.USER_CD , B.USER_NM , B.NODE_CD ORDER BY MIN(A.WORK_YMD), B.USER_NM

    /* Attd01Mapper.selectShiftSchNoCount */
    SELECT COUNT(*)
	FROM TB_SHIFT_SCH_MGMT
	WHERE CMPNY_CD = #{gvCmpnyCd}
	  AND SITE_CD = #{siteCd}
	  AND SHIFT_NO = #{shiftNo}

/* Attd01Mapper.selectShiftCd */
SELECT FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, CONCAT('SHIFT_CD-', #{siteCd}))
FROM DUAL

mapper.insert:
    /* Attd01Mapper.insertShiftSch */
    INSERT TB_SHIFT_SCH_MGMT (
		CMPNY_CD
		, SITE_CD
		, SHIFT_CD
		, SHIFT_NO

		, SHIFT_PTRN_CNT
		, SHIFT_TEAM_CNT
		, SHIFT_CYCLE_DAYS
		, USE_YN

		, INSERT_NO
		, INSERT_DATE
		, UPDATE_NO
		, UPDATE_DATE
	)
	VALUES (
		#{gvCmpnyCd}
		, #{siteCd}
		, #{shiftCd}
		, #{shiftNo}

		, #{shiftPtrnCnt}
		, #{shiftTeamCnt}
		, #{shiftCycleDays}
		, #{useYn}

		, #{gvUserCd}
		, NOW()
		, #{gvUserCd}
		, NOW()
	)

    /* Attd01Mapper.insertShiftSchPtrn */
    INSERT TB_SHIFT_SCH_PTRN_MGMT (
		CMPNY_CD
		, SITE_CD
		, SHIFT_CD
		, PTRN_IDX
		, SCH_CD

		, INSERT_NO
		, INSERT_DATE
		, UPDATE_NO
		, UPDATE_DATE
	)
	VALUES (
		#{gvCmpnyCd}
		, #{siteCd}
		, #{shiftCd}
		, #{ptrnIdx}
		, #{schCd}

		, #{gvUserCd}
		, NOW()
		, #{gvUserCd}
		, NOW()
	)

    /* Attd01Mapper.insertShiftSchTeam */
    INSERT TB_SHIFT_SCH_TEAM_META_INFO (
		CMPNY_CD
		, SITE_CD
		, SHIFT_CD
		, TEAM_IDX
		, TEAM_NM

		, INSERT_NO
		, INSERT_DATE
		, UPDATE_NO
		, UPDATE_DATE
	)
	VALUES (
		#{gvCmpnyCd}
		, #{siteCd}
		, #{shiftCd}
		, #{teamIdx}
		, #{teamNm}

		, #{gvUserCd}
		, NOW()
		, #{gvUserCd}
		, NOW()
	)

    /* Attd01Mapper.insertShiftSchAssign */
    INSERT TB_SHIFT_SCH_ASSIGN_MGMT (
		CMPNY_CD
		, SITE_CD
		, SHIFT_CD

		, TEAM_IDX
		, DAY_NO
		, ASSIGN_YN
		, SCH_CD

		, INSERT_NO
		, INSERT_DATE
		, UPDATE_NO
		, UPDATE_DATE
	)
	VALUES (
		#{gvCmpnyCd}
		, #{siteCd}
		, #{shiftCd}

		, #{teamIdx}
		, #{dayNo}
		, #{assignYn}
		, #{schCd}

		, #{gvUserCd}
		, NOW()
		, #{gvUserCd}
		, NOW()
	)

mapper.select:
/* Attd01Mapper.selectShiftSchInfoList */ SELECT A.CMPNY_CD AS cmpnyCd , A.SITE_CD AS siteCd , A.SHIFT_CD AS shiftCd , A.SHIFT_NO AS shiftNo , A.SHIFT_PTRN_CNT AS shiftPtrnCnt , A.SHIFT_TEAM_CNT AS shiftTeamCnt , A.SHIFT_CYCLE_DAYS AS shiftCycleDays , '0' AS regUserCnt , A.USE_YN AS useYn , GROUP_CONCAT(B.SCH_NM ORDER BY B.DAY_NO SEPARATOR ' / ') AS schNmList FROM TB_SHIFT_SCH_MGMT A INNER JOIN ( SELECT A.CMPNY_CD , A.SITE_CD , A.SHIFT_CD , A.TEAM_IDX , A.DAY_NO , A.SCH_CD ,IFNULL(CONCAT(B.SCH_NO, '(', B.FST_SCH_STR_TIME, '~', B.FST_SCH_END_TIME, ')'), 'OFF') SCH_NM FROM TB_SHIFT_SCH_ASSIGN_MGMT A LEFT OUTER JOIN TB_SCH_MGMT B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.SCH_CD = B.SCH_CD ) WHERE A.TEAM_IDX = '1' ) B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.SHIFT_CD = B.SHIFT_CD ) WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd}
AND A.SITE_CD = #{siteCd}
AND A.SHIFT_NO = #{shiftNo}
AND A.SHIFT_CYCLE_DAYS = #{shiftCycleDays}
AND A.USE_YN = #{useYn}
GROUP BY A.CMPNY_CD , A.SITE_CD , A.SHIFT_CD , A.SHIFT_NO , A.SHIFT_PTRN_CNT , A.SHIFT_TEAM_CNT , A.SHIFT_CYCLE_DAYS , A.USE_YN

    /* Attd01Mapper.selectShiftPatternInfoList */
    SELECT 
		A.CMPNY_CD     AS cmpnyCd
		, A.SITE_CD    AS siteCd
		, A.SHIFT_CD   AS shiftCd
		, A.PTRN_IDX   AS ptrnIdx
		, A.SCH_CD     AS schCd
	FROM TB_SHIFT_SCH_PTRN_MGMT A
	WHERE A.CMPNY_CD = #{gvCmpnyCd}
	  AND A.SITE_CD  = #{siteCd}
	  AND A.SHIFT_CD = #{shiftCd}

    /* Attd01Mapper.selectShiftTeamInfoList */
	SELECT 
		A.CMPNY_CD     AS cmpnyCd
		, A.SITE_CD    AS siteCd
		, A.SHIFT_CD   AS shiftCd
		, A.TEAM_IDX   AS teamIdx
		, A.TEAM_NM    AS teamNm
	FROM TB_SHIFT_SCH_TEAM_META_INFO A
	WHERE A.CMPNY_CD = #{gvCmpnyCd}
	  AND A.SITE_CD  = #{siteCd}
	  AND A.SHIFT_CD = #{shiftCd}

    /* Attd01Mapper.selectShiftAssignInfoList */
	SELECT 
		A.CMPNY_CD     AS cmpnyCd
		, A.SITE_CD    AS siteCd
		, A.SHIFT_CD   AS shiftCd
		, A.TEAM_IDX   AS teamIdx
		, A.DAY_NO     AS dayNo
		, A.ASSIGN_YN  AS assignYn
		, A.SCH_CD     AS schCd
	FROM TB_SHIFT_SCH_ASSIGN_MGMT A
	WHERE A.CMPNY_CD = #{gvCmpnyCd}
	  AND A.SITE_CD  = #{siteCd}
	  AND A.SHIFT_CD = #{shiftCd}
